/* Exact problem-specific diagrams and paused, inspectable solution models. */
"use strict";
(() => {
let data;const players=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const load=()=>data??(data=fetch('problem-visual-models.json?v=question-visuals-3').then(r=>{if(!r.ok)throw Error('Problem model data unavailable');return r.json();}));
const el=(tag,txt,cls)=>{const e=document.createElement(tag);if(txt!==undefined)e.textContent=txt;if(cls)e.className=cls;return e;};
async function mount(host){if(host.dataset.loaded)return;const fallbackMarkup=host.innerHTML;host.dataset.loaded='loading';try{const all=await load(),m=all[host.dataset.problemVisual];if(!m)throw Error('Missing problem model');host.replaceChildren();host.append(el('h4','Visual solution aid'),el('p',m.reading,'problem-reading'));const controls=el('div',undefined,'problem-controls'),q={};for(const [key,label] of [['reset','Restart'],['prev','Previous step'],['play','Play'],['next','Next step']]){q[key]=el('button',label);q[key].type='button';controls.append(q[key]);}const speed=el('select');speed.setAttribute('aria-label','Solution playback speed');for(const v of [.5,1,2]){const option=el('option',v+'×');option.value=v;option.selected=v===1;speed.append(option);}controls.append(el('label','Speed'),speed);const seek=el('input');seek.type='range';seek.min=0;seek.step=1;seek.setAttribute('aria-label','Choose a solution checkpoint');const count=el('span',undefined,'problem-counter'),progress=el('div',undefined,'problem-progress');progress.append(seek,count);if(m.frames.length>1)host.append(controls,progress);const stage=el('div',undefined,'problem-stage');stage.tabIndex=0;const caption=el('p',undefined,'problem-caption');caption.setAttribute('aria-live','polite');const printRoot=el('div',undefined,'teaching-print');host.append(stage,caption,el('p',m.scope,'problem-scope'),printRoot);const api=TeachingTransitions.raw({host,model:m,stage,caption,seek,progress:count,speed,play:q.play,prev:q.prev,next:q.next,reset:q.reset,printRoot});players.push(api);host.dataset.loaded='true';}catch(e){host.innerHTML=fallbackMarkup;host.dataset.loaded='error';host.append(el('p','The interactive aid could not load. Its printed first diagram and full written solution remain available.'));console.error(e);}}

const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)mount(e.target);else players.find(p=>p.host===e.target)?.pause();}),{rootMargin:'200px'});document.querySelectorAll('[data-problem-visual]').forEach(h=>observer.observe(h));
addEventListener('beforeprint',()=>{players.forEach(p=>p.pause());document.querySelectorAll('details.exam-solution').forEach(e=>{e.dataset.problemPrintOpen=String(e.open);e.open=true;});});
addEventListener('afterprint',()=>document.querySelectorAll('details[data-problem-print-open]').forEach(e=>{e.open=e.dataset.problemPrintOpen==='true';delete e.dataset.problemPrintOpen;}));
document.addEventListener('visibilitychange',()=>{if(document.hidden)players.forEach(p=>p.pause());});
window.ProblemVisuals={ready:mount,players};
})();
